add_action( 'woocommerce_order_actions_end', 'perfectpixel_complete_order_button' );
add_action( 'woocommerce_process_shop_order_meta', 'perfectpixel_complete_order_button_save', 60 );

function perfectpixel_complete_order_button( $order_id ) {
	$order = wc_get_order( $order_id );
	if ( $order && ! $order->has_status( array( 'completed', 'refunded', 'cancelled' ) ) ) {
		echo '<li class="wide"><button type="submit" class="button" name="perfectpixel_complete_order" value="1" style="width:100%">Ολοκλήρωση παραγγελίας</button></li>';
	}
}

// Runs after WooCommerce saved the order data (priority 40), so our status wins.
function perfectpixel_complete_order_button_save( $order_id ) {
	if ( empty( $_POST['perfectpixel_complete_order'] ) || ! current_user_can( 'edit_shop_orders' ) ) {
		return;
	}
	$order = wc_get_order( $order_id );
	if ( $order && ! $order->has_status( 'completed' ) ) {
		$order->update_status( 'completed', 'Ολοκληρώθηκε από το κουμπί «Ολοκλήρωση παραγγελίας».' );
	}
}
